contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 drugs) public {
        c.seedMarket(drugs);
        c.getFreeKilo();
        uint256 produced = c.getDrugsSinceLastCollect(address(this));
        assert(
            c.initialized()
            && c.marketDrugs() == drugs
            && c.getMyKilo() == c.STARTING_KILOS()
            && c.Kilos(address(this)) == c.STARTING_KILOS()
            && produced <= c.DRUGS_TO_PRODUCE_1KILO() * c.getMyKilo()
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
