    function run() public {
        c.seedMarket(1);
        c.getFreeKilo();
        uint256 kilos = c.Kilos(address(this));
        bool reverted;
        try c.getFreeKilo() { reverted = false; } catch { reverted = true; }
        assert(reverted && kilos == c.STARTING_KILOS());
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 seeded, uint256 amount) public payable {
        c.seedMarket(seeded);
        uint256 balBefore = address(c).balance;
        c.buyDrugs{value: amount}();
        uint256 bought = c.calculateDrugBuy(amount, balBefore - amount);
        uint256 fee = c.devFee(bought);
        uint256 claimed = c.claimedDrugs(address(this));
        assert(claimed == bought - fee && fee <= bought);
    }
    receive() external payable {}
}

