contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 drugs, uint256 amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        c.seedMarket{value: 0}(drugs);
        uint256 balBefore = address(c).balance;
        uint256 claimedBefore = c.claimedDrugs(address(this));
        c.buyDrugs{value: amount}();
        uint256 drugsBought = c.calculateDrugBuy(amount, balBefore - amount);
        uint256 expected = c.devFee(drugsBought);
        assert(c.claimedDrugs(address(this)) == claimedBefore + drugsBought - expected);
    }
    receive() external payable {}
}

